import type { ObserverJson } from '../../../contracts/observerContract.js';
export type Role = 'input' | 'judgment' | 'action' | 'output' | 'memory' | 'own' | 'store';
export type BlockSpec = [id: string, label: string, process: string, role: Role];
export type ViewNodeSpec = [id: string, block: string, col: number, row: number, label: string, description: string, sources: string[], span?: number];
export type ViewBoxSpec = [id: string, block: string, label: string, description: string, sources: string[]];
export type LinkSpec = [from: string, to: string, background?: boolean];
export const BLOCKS: BlockSpec[];
export const VIEW_BOXES: ViewBoxSpec[];
export const LAYOUT_ID: string;
export const DEFAULT_PLACEMENT: string;
export function parsePlacement(text: string, ids?: string[]): { cells: Map<string, [col: number, row: number, span: number]>; problems: string[] };
export const VIEW_NODES: ViewNodeSpec[];
export const VIEW_LINKS: LinkSpec[];
export const ROLES: Role[];
export const VIEW_INDEX: Map<string, ViewNodeSpec>;
export const BLOCK_INDEX: Map<string, BlockSpec>;
export function roleOf(id: string): Role;
export function viewNodeOf(node: string | undefined, input?: ObserverJson | unknown, output?: ObserverJson | unknown): string | null;
export function viewHandoff(event: { fromNode?: string; toNode?: string; input?: unknown; output?: unknown }): [string | null, string | null];
export const BLOCK_PAD: { side: number; top: number; bottom: number };
export const NODE_W: number; export const NODE_H: number; export const PITCH_X: number; export const PITCH_Y: number; export const ORIGIN_X: number; export const ORIGIN_Y: number;
export interface Box { x: number; y: number; w: number; h: number }
export interface NodeBox extends Box { col: number; row: number; block: string; shift: [number, number] }
export interface GridLayout { width: number; height: number; boxes: Map<string, NodeBox>; blocks: Map<string, Box> }
export type Positions = Record<string, [number, number]>;
export function gridLayout(blocks: BlockSpec[], nodes: ViewNodeSpec[], positions?: Positions): GridLayout;
export const CURRENT_LAYOUT: GridLayout;
export function movedPositions(layout: GridLayout, ids: string[], dx: number, dy: number): Positions;
export function customPositions(layout: GridLayout): Positions;
export function savedPositions(value: unknown, ids?: string[], layoutId?: string): Positions;
export type Curve = [[number, number], [number, number], [number, number], [number, number]];
export function edgeCurve(a: Box, b: Box, offset?: number): Curve;
export function bezierAt(points: Curve, t: number): [number, number];
export function curvePath(points: Curve): string;
export type Route = { kind: 'curve'; points: Curve } | { kind: 'poly'; points: [number, number][] };
export function gutterRoute(a: NodeBox, b: NodeBox, offset?: number): Route;
export function routePath(route: Route): string;
export function routePoint(route: Route, t: number): [number, number];
export function routeTable(layout: GridLayout, links: LinkSpec[]): Map<string, Route & { from: string; to: string; background: boolean }>;
export function blockRoutes(layout: GridLayout, links: LinkSpec[]): Map<string, Route & { from: string; to: string }>;
export function detailLevel(picked: 1 | 2 | 3 | null | undefined, zoom: number): 1 | 2 | 3;
export function textWidth(text: string, size: number): number;
export function fitText(text: string, size: number, width: number): string;
export const IO_FONT: number; export const IO_PITCH: number;
export function ioRows(box: Box, input: { gloss: string; key: string; value: string }[], output: { gloss: string; key: string; value: string }[]): { mark: string; name: string; value: string; y: number }[];
